(() => {
  const rail = document.querySelector("[data-activity-rail-content='true']");
  const rowsOf = (heading) => {
    const group = heading.closest("div[class*='space-y-0.5']");
    return group ? group.querySelectorAll("div[class*='group/thread']").length : -1;
  };
  const headings = [
    // This machine's workspace heading comes from the rail, and the rows under it
    // from the merged list: two components, one decision. That is the pair that
    // disagreed, so it is the one asserted first.
    ...rail.querySelectorAll("[data-testid='local-group-heading']"),
    ...rail.querySelectorAll("[data-testid='merged-group-heading']"),
  ];
  if (headings.length === 0) throw new Error('no workspace heading in the merged list');
  const results = [];
  const fold = (heading, label) => new Promise((resolve) => {
    const before = rowsOf(heading);
    if (before === 0) { resolve(label + ':no-rows'); return; }
    heading.closest("div").querySelector("button").click();
    setTimeout(() => {
      const after = rowsOf(heading);
      heading.closest("div").querySelector("button").click();
      setTimeout(() => {
        const back = rowsOf(heading);
        resolve(label + ':' + before + '->' + after + '->' + back + (after === 0 && back === before ? ' OK' : ' BAD'));
      }, 260);
    }, 260);
  });
  return Promise.all(headings.slice(0, 3).map((heading, index) =>
    fold(heading, index === 0 ? 'first' : 'next'))).then((parts) => {
    const bad = parts.filter(part => part.includes('BAD'));
    if (bad.length > 0) throw new Error('a heading did not fold its rows: ' + parts.join(' | '));
    if (parts.every(part => part.includes('no-rows'))) throw new Error('no group had rows to fold: ' + parts.join(' | '));
    return parts.join(' | ');
  });
})()

(() => {
  const heading = [...document.querySelectorAll("[data-testid='merged-group-heading']")]
    .find(node => (node.textContent || '').includes('图表脚本'));
  if (!heading) throw new Error('the host workspace heading is not in the list');
  const header = heading.closest('div');
  const buttons = [...header.querySelectorAll('button')];
  const menu = buttons.find(button => button.getAttribute('aria-haspopup') === 'menu');
  const add = buttons[buttons.length - 1];
  if (!menu || !add) throw new Error('the heading is missing a control: ' + buttons.map(b => b.getAttribute('aria-label')).join(' | '));
  // The local heading's order: the actions menu, then the way into the workspace.
  if (!(menu.compareDocumentPosition(add) & Node.DOCUMENT_POSITION_FOLLOWING))
    throw new Error('the new-chat control precedes the actions menu');
  // The pin marker rides at the row's end, next to the controls, as it does on
  // this app's own heading. Measured with the menu *closed*: an open menu carries
  // a pin icon of its own, and a class list cannot say where anything is anyway.
  const pin = header.querySelector(':scope > svg.lucide-pin');
  if (!pin) throw new Error('the pinned heading shows no pin marker');
  const nameBox = heading.getBoundingClientRect();
  const pinBox = pin.getBoundingClientRect();
  const menuBox = menu.getBoundingClientRect();
  if (pinBox.left <= nameBox.right)
    throw new Error('the pin sits against the name: ' + Math.round(pinBox.left) + ' vs ' + Math.round(nameBox.right));
  if (pinBox.right > menuBox.left + 1)
    throw new Error('the pin is not before the controls: ' + Math.round(pinBox.right) + ' vs ' + Math.round(menuBox.left));

  menu.click();
  // React commits the panel on its own tick, so the menu's contents are read a
  // frame later rather than in the click's own task.
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        const items = [...document.querySelectorAll("[role='menuitem']")].map(node => (node.textContent || '').trim());
        const pinItems = items.filter(text => text === '置顶' || text === '取消置顶');
        if (pinItems.length !== 1)
          throw new Error('the menu offers ' + pinItems.length + ' pin items: ' + items.join(' | '));
        if (!items.includes('选择聊天'))
          throw new Error('the menu has no select-chats item: ' + items.join(' | '));
        if (!items.includes('重命名'))
          throw new Error('the menu has no rename item: ' + items.join(' | '));
        if (items.length !== 4)
          throw new Error('the menu is not [rename, pin, select chats, delete]: ' + items.join(' | '));
