(() => {
  const names = [...document.querySelectorAll("[data-testid='local-group-heading']")]
    .map(node => (node.textContent || '').trim());
  if (names.length < 4) throw new Error('too few local workspace headings to judge an order: ' + JSON.stringify(names));
  // This fixture pins two of this machine's workspaces ("多巴胺与决策", "稀疏注意力复现"),
  // so the rule is that every pinned group precedes every unpinned one — not that
  // any particular one leads, since the two pinned ones are theirs to order.
  const pinned = ['多巴胺与决策', '稀疏注意力复现'];
  const unpinned = ['单细胞转录组', '临时会话'];
  if (pinned.some(name => names.indexOf(name) < 0)) throw new Error('a pinned workspace is not listed: ' + JSON.stringify(names));
  if (unpinned.some(name => names.indexOf(name) < 0)) throw new Error('an unpinned workspace is not listed: ' + JSON.stringify(names));
  const lastPinned = Math.max(...pinned.map(name => names.indexOf(name)));
  const firstUnpinned = Math.min(...unpinned.map(name => names.indexOf(name)));
  if (lastPinned > firstUnpinned) throw new Error('an unpinned workspace leads a pinned one: ' + JSON.stringify(names));
  return names.join(' / ');
})()

(() => {
  const msgs = [...document.querySelectorAll('[data-message-id]')];
  if (msgs.length === 0) throw new Error('the transcript did not render');
  const scroller = msgs[0].closest("[data-chat-scroll='true']");
  if (!scroller) throw new Error('no transcript viewport');
  const distance = scroller.scrollHeight - scroller.clientHeight - scroller.scrollTop;
  // Within a few px of the bottom: the newest message is what the reader sees.
  if (Math.abs(distance) > 8)
    throw new Error('the transcript did not open at the newest message: ' + Math.round(distance) + 'px from the bottom');
  // The last message is inside the viewport, and the first is not: proof that
  // "at the bottom" is about the newest turn, not an accident of a short page.
  const box = scroller.getBoundingClientRect();
  const last = msgs[msgs.length - 1].getBoundingClientRect();
  if (last.bottom > box.bottom + 8 || last.top < box.top - 8)
    throw new Error('the newest message is not in view');
  return 'distance=' + Math.round(distance) + ' scrollHeight=' + Math.round(scroller.scrollHeight);
})()

