  if (!toggle) throw new Error('the toggle does not offer to fold it again');
  // Drawn *under* the conversation it came from: the row right after it, one
  // level in. The fork's own last message is newer than its parent's, so a list
  // that ranked rows by time put it above its parent — pressing `+` then looked
  // like it revealed nothing, because the row had already been on screen.
  const rows = [...document.querySelectorAll("div[class*='group/thread']")];
