    throw new Error('the fork is not directly under its conversation: row ' + rows.indexOf(fork) + ' against ' + rows.indexOf(parent));
  const indent = el => Number.parseInt(getComputedStyle(el).paddingLeft, 10);
  if (indent(fork) <= indent(parent))
    throw new Error('the fork is not indented under it: ' + indent(fork) + ' against ' + indent(parent));
