(() => {
  const field = document.querySelector('textarea');
  // The placeholder describes the task and points at `/`, as this app's own
  // composer does. What it must not do is name the machine: that is the rail's
  // business, and this app's composers never state it.
  if (field.placeholder !== '描述任务，按 / 使用工具或技能，按 # 引用会话')
    throw new Error('the placeholder does not match the local composer: ' + field.placeholder);
  const rows = [...document.querySelectorAll("[role='option']")].map(r => (r.textContent || '').trim());
  // The reference hand-off leads when there is another conversation to point
  // at — the row the phone's `/` also offers — and the compact request follows
  // it, in the order the composer builds them.
  if (!rows[0].startsWith('引用对话')) throw new Error('the reference hand-off does not lead: ' + JSON.stringify(rows));
  if (!rows[1].startsWith('压缩上下文')) throw new Error('the compact request does not follow it: ' + JSON.stringify(rows));
  // Then the host's skills, by the name the host resolves, each with what it
  // does — a list of bare names is not a menu anyone can choose from.
  const skill = rows.find(r => r.startsWith('/Paper Search'));
  if (!skill) throw new Error('the host skills are not in the menu: ' + JSON.stringify(rows));
  if (!skill.includes('检索文献')) throw new Error('a skill row carries no description: ' + skill);
