  if (!host) throw new Error('the host direction is not on the page');
  const t = host.innerText;
  for (const wanted of ['正在控制', '待命', '离线', '添加设备'])
    if (!t.includes(wanted)) throw new Error('the device list is missing ' + wanted + ': ' + t.slice(0, 400));
