  if (rows.length !== 3) throw new Error('expected three device rows, got ' + rows.length + ': ' + JSON.stringify(rows));
  // Every row is the whole record of a connection, so every row can unpair it.
  const unpairRows = rows.filter(r => r.includes('解除配对'));
  if (unpairRows.length !== 3) throw new Error('expected every row to offer 解除配对, got ' + unpairRows.length + ': ' + JSON.stringify(rows));
  // Only the live standby device is offered control: the machine's controller
  // already has it, and an offline device cannot be handed it.
  const takeoverRows = rows.filter(r => r.includes('让这台控制'));
  if (takeoverRows.length !== 1) throw new Error('expected exactly one row to offer 让这台控制, got ' + takeoverRows.length + ': ' + JSON.stringify(rows));
  if (!takeoverRows[0].includes('实验室的 MacBook Air')) throw new Error('the takeover action is on the wrong device: ' + takeoverRows[0]);
  // The row is a record, not a door: no page to open, and none of that page's
  // actions left behind in the list.
  if (t.includes('断开') || t.includes('删除')) throw new Error('the list still carries the removed per-client page actions: ' + t.slice(0, 400));
  return 'rows=' + rows.length;
})()

