(() => {
  // The transcript is an `inverted` list: react-native-web flips the scroll view
  // and flips every cell back, so the newest row is at the bottom and the text
  // reads the right way up. A refresh control's wrapper must not take the
  // inversion a third time (native does not do it); when it does, the whole
  // transcript is drawn upside down — glyphs mirrored and rows reversed. cdp.mjs
  // neutralises that extra flip in the page for mobile captures; this fails if it
  // stops happening, and fails if the flip stops needing neutralisation, so the
  // workaround cannot rot into dead code unnoticed.
  const mirrors = (el) => {
    const parts = getComputedStyle(el).transform.match(/^matrix\(([^)]+)\)$/);
    if (!parts) return false;
    const [a, b, c, d, e, f] = parts[1].split(',').map(Number);
    return a === 1 && b === 0 && c === 0 && d === -1 && e === 0 && f === 0;
  };
  const scrollers = [...document.querySelectorAll('div')]
    .filter((el) => el.scrollHeight > el.clientHeight + 10 && el.clientHeight > 400);
  if (!scrollers.length) throw new Error('the transcript list is not on screen');
  const scroller = scrollers.sort((a, b) => b.getBoundingClientRect().height - a.getBoundingClientRect().height)[0];
  const blocks = [...scroller.querySelectorAll('div,span,p')]
    .filter((el) => !el.children.length && (el.innerText || '').trim().length > 20);
  if (!blocks.length) throw new Error('the transcript has no text to read');
  let worst = 0;
  for (const block of blocks) {
    let flips = 0;
    for (let el = block; el && el !== document.body; el = el.parentElement) if (mirrors(el)) flips += 1;
    worst = Math.max(worst, flips);
  }
  if (worst > 2)
    throw new Error('the transcript sits under ' + worst + ' vertical flips, so it reads upside down');
  if (!(window.__shotUnflipped >= 1))
    throw new Error('the harness did not neutralise the inverted list\'s extra flip, so the orientation of this capture is unproven (drop UNFLIP_INVERTED_LIST in cdp.mjs if react-native-web stopped nesting it)');
  return 'the transcript is not mirrored (vertical flips: ' + worst + ')';
})()

(() => {
  // The fold's own row carries the same counts in its spoken label, so the run
  // is the row whose label *starts* with the tool wording.
  const run = [...document.querySelectorAll('[role=button]')]
    .find(node => (node.getAttribute('aria-label') || '').startsWith('工具调用'));
  if (!run) throw new Error('no step summary row inside the opened process');
  run.click();
  return 'step run opened';
})()

(() => {
  const run = [...document.querySelectorAll('[role=button]')]
    .find(node => (node.getAttribute('aria-label') || '').startsWith('工具调用'));
  if (!run) throw new Error('the step summary row is gone');
  // The reply block draws the summary line and, once opened, the rows under
  // it — one child either way until the press lands.
  if (run.parentElement.children.length < 2)
    throw new Error('the step run did not open: only its summary line is drawn');
  return 'the run is open';
})()

(() => {
  // Two machines, each with its own two actions and nothing else: the row
  // used to carry a highlight and a check mark for the machine in use, which
  // beside those two actions read as a third control on a row that cannot be
  // pressed at all (see DesktopsScreen).
  const rows = [...document.querySelectorAll('[aria-label]')].filter(el =>
    ['实验室的 MacBook Pro', '办公室主机'].includes(el.getAttribute('aria-label')));
  if (rows.length !== 2) throw new Error('the list does not carry both machines by name: ' + rows.length);
  for (const row of rows) {
    const card = row.parentElement;
    if (getComputedStyle(card).backgroundColor === 'rgb(232, 240, 255)') throw new Error('the card is still painted as the current machine');
    const actions = [...card.querySelectorAll('[role=button]')];
    if (actions.length !== 2) throw new Error('a machine offers ' + actions.length + ' actions, not the two it has');
    const glyphs = card.querySelectorAll('svg').length;
    if (glyphs !== 2) throw new Error('the row draws ' + glyphs + ' glyphs, not its two actions');
  }
  return 'two descriptions, two actions each, nothing marked';
})()

(() => {
  // A row is not a chooser: tapping a machine's name on this page used to bind
  // it and leave for the session list. Switching is asked for where a
  // conversation is opened, so a tap here has to do nothing at all.
  const row = [...document.querySelectorAll('[aria-label]')]
    .find(el => el.getAttribute('aria-label') === '办公室主机');
  if (!row) throw new Error('the other machine is not on the list');
  row.click();
  return 'tapped 办公室主机';
})()

(() => {
  const text = document.body.innerText;
  if (!text.includes('已配对的桌面端')) throw new Error('the tap left the paired list: ' + text.slice(0, 200));
  if (text.includes('工作区') && !text.includes('已配对的桌面端')) throw new Error('the tap went to the session list');
  return 'still on the paired list';
})()

(() => {
  const text = document.body.innerText;
  // The machine's own page names it, offers its label fields, and lists the
  // settings that live on it. Every one of these used to be on the phone's
  // settings screen; none of them may come back there.
  for (const wanted of ['实验室的 MacBook Pro', '设备标识', '名称', '图标', '该桌面端的设置', '自动化与审批', '模型可见性', '提供商与模型', '技能管理', '定时任务设置']) {
    if (!text.includes(wanted)) throw new Error('the device page is missing ' + wanted + ': ' + text.slice(0, 300));
  }
  // And no connection step: every paired machine keeps its own live runtime,
  // so its settings are read over that machine's own connection. The row that
  // used to ask to "connect to this desktop" first is gone.
  if (text.includes('连接该桌面端')) throw new Error('the page still asks to connect first: ' + text.slice(0, 300));
  const grid = [...document.querySelectorAll('[role=radio]')];
  if (grid.length < 20) throw new Error('the icon grid is not on the page: ' + grid.length);
  return grid.length + ' icons, no connection step';
})()

(() => {
  // Picking an icon writes it through the phone's label store and the page
  // reads it back: a picker that stores an id nothing reads looks identical.
  const option = [...document.querySelectorAll('[role=radio]')].find(el => el.getAttribute('aria-label') === '发布机');
  if (!option) throw new Error('the rocket icon is missing from the grid');
  option.click();
  return 'picked the rocket';
})()

(() => {
  const option = [...document.querySelectorAll('[role=radio]')].find(el => el.getAttribute('aria-label') === '发布机');
  const picked = getComputedStyle(option).backgroundColor;
  if (picked !== 'rgb(232, 240, 255)') throw new Error('the picked icon is not marked: ' + picked);
  return picked;
})()

(() => {
  const text = document.body.innerText;
  for (const wanted of ['手机本机', '语言', '微信公众号', '检查更新']) {
    if (!text.includes(wanted)) throw new Error('the phone settings are missing ' + wanted);
  }
  for (const gone of ['当前桌面端', '模型可见性', '定时任务设置', '技能管理']) {
    if (text.includes(gone)) throw new Error('a device setting is still on the phone screen: ' + gone);
  }
  return 'phone-only settings';
})()

(() => {
  const labels = [...document.querySelectorAll('[role=radio]')].map(node => node.getAttribute('aria-label'));
  for (const wanted of ['跟随系统', '浅色', '深色', '小', '中', '大', '特大']) {
    if (!labels.includes(wanted)) throw new Error('the appearance page is missing ' + wanted + ': ' + JSON.stringify(labels));
  }
  // Each size chip is set at the size it picks, so the choice reads as a size.
  const chipSize = label => getComputedStyle(document.querySelector(`[role=radio][aria-label="${label}"]`).firstElementChild).fontSize;
  const sizes = ['小', '中', '大', '特大'].map(chipSize);
  if (new Set(sizes).size !== 4) throw new Error('the size chips are not all different: ' + JSON.stringify(sizes));
  // The reply level is this phone's own, offers both levels, and ships on 默认.
  const replyLabels = [...document.querySelectorAll('[role=radio]')].map(node => node.getAttribute('aria-label'));
  for (const wanted of ['默认', '详细']) {
    if (!replyLabels.includes(wanted)) throw new Error('the reply level is missing ' + wanted + ': ' + JSON.stringify(replyLabels));
  }
  // A checked chip is painted with the accent border (react-native-web leaves
  // `aria-checked` unset on a radio).
  const checkedChip = label => getComputedStyle(document.querySelector(`[role=radio][aria-label="${label}"]`)).borderColor === 'rgb(37, 99, 235)';
  if (!checkedChip('默认') || checkedChip('详细'))
    throw new Error('the reply level does not start on 默认');
  return 'appearance options ok: ' + JSON.stringify(sizes);
})()

(() => {
  // The header is built from `desktopSettings.<level>`, so a level whose
  // title key is missing paints the key itself instead of failing loudly. It
  // is the heading in the row that also holds the back control: the list
  // behind the sheet has headings of its own and comes first in the document.
  const back = document.querySelector('[aria-label="返回"]');
  const bar = back && back.parentElement && back.parentElement.parentElement;
  const header = bar ? bar.querySelector('[role=heading]') : null;
  if (!header) throw new Error('the appearance level has no header');
  const title = (header.textContent || '').trim();
  if (title !== '外观') throw new Error('the appearance header is not its title: ' + title);
  // Each group shows exactly the stored choice, and nothing at all is stored
  // until the reader chooses: the default is to follow the phone, at the
  // size the app was designed at.
  const stored = JSON.parse(window.localStorage.getItem('future.mobile.appearance') || 'null') || { themeMode: 'system', fontSize: 'medium', replyDetail: 'default' };
  const themeLabel = { system: '跟随系统', light: '浅色', dark: '深色' }[stored.themeMode];
  const sizeLabel = { small: '小', medium: '中', large: '大', xlarge: '特大' }[stored.fontSize];
  const replyLabel = { default: '默认', detailed: '详细' }[stored.replyDetail || 'default'];
  const accent = 'rgb(37, 99, 235)';
  // One checked chip per group, in the order the groups are drawn.
  const chosen = [...document.querySelectorAll('[role=radio]')]
    .filter(node => getComputedStyle(node).borderColor === accent)
    .map(node => node.getAttribute('aria-label'));
  if (JSON.stringify(chosen) !== JSON.stringify([themeLabel, sizeLabel, replyLabel])) {
    throw new Error('the checked choices do not match the stored appearance ' + JSON.stringify(stored) + ': ' + JSON.stringify(chosen));
  }
  return 'header and checked appearance ok';
})()

(() => {
  const stored = JSON.parse(window.localStorage.getItem('future.mobile.appearance') || '{}');
  if (stored.replyDetail !== 'detailed') throw new Error('the reply level was not stored: ' + JSON.stringify(stored));
  const checked = label => getComputedStyle(document.querySelector(`[role=radio][aria-label="${label}"]`)).borderColor === 'rgb(37, 99, 235)';
  if (!checked('详细') || checked('默认')) throw new Error('the reply level did not switch to 详细');
  return 'reply level stored and painted';
})()

(() => {
  const stored = JSON.parse(window.localStorage.getItem('future.mobile.appearance') || '{}');
  if (stored.replyDetail !== 'default') throw new Error('the reply level did not switch back: ' + JSON.stringify(stored));
  const checked = label => getComputedStyle(document.querySelector(`[role=radio][aria-label="${label}"]`)).borderColor === 'rgb(37, 99, 235)';
  if (!checked('默认') || checked('详细')) throw new Error('the reply level did not switch back on screen');
  return 'reply level back on 默认';
})()

(() => {
  const painted = colour => [...document.querySelectorAll('div')].some(node => getComputedStyle(node).backgroundColor === colour);
  if (!painted('rgb(11, 18, 32)')) throw new Error('the dark canvas was not painted');
  if (!painted('rgb(21, 30, 46)')) throw new Error('the dark surface was not painted');
  const stored = window.localStorage.getItem('future.mobile.appearance');
  if (!stored || !stored.includes('"themeMode":"dark"')) throw new Error('the scheme was not stored: ' + stored);
  return 'dark painted and stored';
})()

(() => {
  // The screens behind the sheet are rebuilt, not only the chips in it: a
  // colour or size frozen at mount would leave the app on the old theme.
  const dark = [...document.querySelectorAll('div')].filter(node => getComputedStyle(node).backgroundColor === 'rgb(21, 30, 46)');
  if (dark.length === 0) throw new Error('the session list is not on the dark surface');
  const stored = JSON.parse(window.localStorage.getItem('future.mobile.appearance'));
  if (stored.fontSize !== 'xlarge') throw new Error('the text size was not stored: ' + JSON.stringify(stored));
  return 'list repainted: ' + JSON.stringify(stored);
})()

(() => {
  const body = [...document.querySelectorAll('div')].find(node => node.children.length === 0 && (node.textContent || '').includes('整理两篇文献的结论对比表'));
  if (!body) throw new Error('the conversation did not open');
  const style = getComputedStyle(body);
  // 15 design points at the largest text size (15 x 1.35, rounded).
  if (style.fontSize !== '20px') throw new Error('message text is not at the largest size: ' + style.fontSize);
  if (style.color !== 'rgb(230, 236, 246)') throw new Error('message text is not the dark ink: ' + style.color);
  const bubble = [...document.querySelectorAll('div')].find(node => getComputedStyle(node).backgroundColor === 'rgb(96, 165, 250)');
  if (!bubble) throw new Error('the user bubble is not painted with the dark accent');
  return 'chat scales and stays dark';
})()

(() => {
  const back = [...document.querySelectorAll('[role=button]')].find(node => (node.getAttribute('aria-label') || '').includes('返回'));
  if (!back) throw new Error('no way back out of the conversation');
  back.click();
  return 'chat closed';
})()

(() => {
  const stored = window.localStorage.getItem('future.mobile.appearance');
  const parsed = stored ? JSON.parse(stored) : {};
  if (parsed.themeMode !== 'system' || parsed.fontSize !== 'medium' || parsed.replyDetail !== 'default') {
    throw new Error('the appearance was left changed: ' + stored);
  }
  return 'profile left on the default appearance';
})()

(() => {
  // Two machines, each a way into itself: the chevron says the row opens
  // something, and nothing is painted as the picked machine. The check this
  // step used to draw on the phone's own machine made the dialog read as a
  // selection with no way to confirm it.
  const names = ['实验室的 MacBook Pro', '办公室主机'];
  const rows = [...document.querySelectorAll('[aria-label]')].filter(el => names.includes(el.getAttribute('aria-label')));
  if (rows.length !== 2) throw new Error('the machine step carries ' + rows.length + ' machines, not the two paired');
  for (const row of rows) {
    const label = row.getAttribute('aria-label');
    const style = getComputedStyle(row);
    if (style.backgroundColor === 'rgb(232, 240, 255)') throw new Error(label + ' is painted as the chosen machine');
    if (style.borderColor === 'rgb(37, 99, 235)') throw new Error(label + ' is outlined as the chosen machine');
    const glyphs = row.querySelectorAll('svg').length;
    if (glyphs !== 1) throw new Error(label + ' draws ' + glyphs + ' glyphs, not the one chevron it is entered by');
  }
  return 'two machines to enter, none marked';
})()

(() => {
  const row = [...document.querySelectorAll('[aria-label]')]
    .find(el => el.getAttribute('aria-label') === '办公室主机');
  if (!row) throw new Error('the second machine is not on the machine step');
  row.click();
  return 'tapped 办公室主机';
})()

(() => {
  // Tapping the row is what goes into that machine: the step that follows is
  // the one that names it — its workspaces, and the action that creates there.
  const text = document.body.innerText;
  if (!text.includes('在 办公室主机 上新建')) throw new Error('the step that follows does not name the machine that was entered: ' + text.slice(0, 200));
  return 'the machine that was entered names the step';
})()

(() => {
  const actions = [...document.querySelectorAll('[role=button][aria-label="桌面端设置"]')];
  if (actions.length !== 2) throw new Error('expected one settings action per machine: ' + actions.length);
  actions[1].click();
  return 'opened the second machine per pair';
})()

(() => {
  const text = document.body.innerText;
  // The machine the phone is not reading is the page that used to open
  // with "Connect to this desktop" and no rows at all.
  for (const wanted of ['办公室主机', '设备标识', '名称', '图标', '该桌面端的设置', '自动化与审批', '模型可见性', '提供商与模型', '技能管理', '定时任务设置']) {
    if (!text.includes(wanted)) throw new Error('the other machine page is missing ' + wanted + ': ' + text.slice(0, 300));
  }
  if (text.includes('连接该桌面端')) throw new Error('the page still asks to connect first: ' + text.slice(0, 300));
  return 'its own settings, with no connection step';
})()

(() => {
  // The settings page is a full-screen modal over the list, and both have a
  // 返回 control: the page's own is the last one in the document.
  const backs = [...document.querySelectorAll('[role=button][aria-label="返回"]')];
  if (backs.length !== 2) throw new Error('expected the page and the list to each offer a back control: ' + backs.length);
  backs[backs.length - 1].click();
  return 'closed the machine page';
})()

(() => {
  const text = document.body.innerText;
  if (!text.includes('已配对的桌面端')) throw new Error('closing the page did not return to the paired list: ' + text.slice(0, 200));
  // Nothing navigated away on its own: the machine whose page was open is not
  // the one the phone reads, and opening its page is not a way to switch.
  if (text.includes('工作区') || text.includes('全部桌面')) throw new Error('the phone ended up on the session list: ' + text.slice(0, 200));
  return 'back on the paired list';
})()

(() => {
  // The other row opens the other machine: each row's action is about the
  // machine that row names, and the page it opens says which one.
  const actions = [...document.querySelectorAll('[role=button][aria-label="桌面端设置"]')];
  if (actions.length !== 2) throw new Error('expected one settings action per machine: ' + actions.length);
  actions[0].click();
  return 'opened the first machine per pair';
})()

(() => {
  const text = document.body.innerText;
  if (!text.includes('实验室的 MacBook Pro')) throw new Error('the first machine page does not name it: ' + text.slice(0, 300));
  if (text.includes('连接该桌面端')) throw new Error('the page still asks to connect first: ' + text.slice(0, 300));
  return 'the first machine names itself too';
})()

(() => {
  const sheet = document.querySelector('[aria-modal=true]') || document.body;
  const text = sheet.innerText || '';
  if (!text.includes('已断开')) throw new Error('the sheet does not say the connection is gone: ' + text.slice(0, 300));
  const labels = [...sheet.querySelectorAll('[role=button]')].map(el => el.getAttribute('aria-label'));
  if (!labels.includes('重新连接')) throw new Error('a dropped connection offers no retry: ' + labels.join(' / '));
  return labels.join(' / ');
})()

(() => {
  const sheet = document.querySelector('[aria-modal=true]') || document.body;
  const text = sheet.innerText || '';
  for (const wanted of ['已连接 · 待命', '已被 实验室的 MacBook Air 接管', '接管会断开 实验室的 MacBook Air', '接管'])
    if (!text.includes(wanted)) throw new Error('the status sheet does not explain or offer the takeover: missing ' + wanted + ': ' + text.slice(0, 400));
  const labels = [...sheet.querySelectorAll('[role=button]')].map(el => el.getAttribute('aria-label'));
  if (!labels.includes('接管')) throw new Error('no takeover action in the sheet: ' + labels.join(' / '));
  return labels.join(' / ');
})()

(() => {
  const sheet = document.querySelector('[aria-modal=true]') || document.body;
  const text = sheet.innerText || '';
  if (!text.includes('已被其他设备接管'))
    throw new Error('the standby machine does not say why it cannot be driven: ' + text.slice(0, 400));
  const labels = [...sheet.querySelectorAll('[role=button]')].map(el => el.getAttribute('aria-label'));
  if (!labels.some(label => label && label.startsWith('接管'))) 
    throw new Error('the picker offers no way to take over: ' + labels.join(' / '));
  return labels.filter(Boolean).join(' / ');
})()

(() => {
  const dot = document.querySelector('[data-testid=connection-dot]');
  if (!dot) throw new Error('no connection dot on screen');
  const color = getComputedStyle(dot).backgroundColor;
  // The warning dot is yellow; success is green. Name both so a palette
  // change fails loudly instead of silently approving the wrong one.
  const warning = getComputedStyle(document.documentElement).getPropertyValue('--x') || '';
  if (color === 'rgb(34, 197, 94)' || color === 'rgb(22, 163, 74)')
    throw new Error('a standby connection is painted as healthy green: ' + color + warning);
  const label = document.querySelector('[role=button][aria-label^="桌面端连接状态"]')?.getAttribute('aria-label');
  if (!label || !label.includes('待命'))
    throw new Error('the badge does not say it is in standby: ' + label);
  return color + ' | ' + label;
})()

(() => {
  const t = document.body.innerText;
  for (const unwanted of ['已被 实验室的 MacBook Air 接管', '接管会断开'])
    if (t.includes(unwanted)) throw new Error('the list page still carries the prompt: ' + unwanted);
  const labels = [...document.querySelectorAll('[role=button]')].map(el => el.getAttribute('aria-label'));
  if (labels.includes('接管')) throw new Error('the list page still offers the takeover action: ' + labels.join(' / '));
  const dot = document.querySelector('[data-testid=connection-dot]');
  if (!dot) throw new Error('the yellow dot is not on screen, so nothing says anything is wrong');
  return getComputedStyle(dot).backgroundColor;
})()

(() => {
  const text = document.body.innerText || '';
  for (const wanted of ['已被 实验室的 MacBook Air 接管', '这台桌面正被另一台设备使用', '接管会断开 实验室的 MacBook Air'])
    if (!text.includes(wanted)) throw new Error('the takeover page is missing ' + wanted + ': ' + text.slice(0, 400));
  const labels = [...document.querySelectorAll('[role=button]')].map(el => el.getAttribute('aria-label'));
  if (!labels.includes('接管')) throw new Error('no takeover action on the page: ' + labels.join(' / '));
  if (document.querySelectorAll('[role=tab]').length > 0) throw new Error('the session list is still on screen under a taken-over machine');
  if (labels.includes('新对话')) throw new Error('the list’s new-conversation button survived the takeover page');
  return 'takeover page';
})()

(() => {
  const t = document.body.innerText;
  for (const wanted of ['已被 实验室的 MacBook Air 接管，现在发不出去。', '接管'])
    if (!t.includes(wanted)) throw new Error('nothing in the conversation explains the refusal: missing ' + wanted + ': ' + t.slice(0, 600));
  const labels = [...document.querySelectorAll('[role=button]')].map(el => el.getAttribute('aria-label'));
  if (!labels.includes('接管')) throw new Error('the conversation offers no way to take it back: ' + labels.join(' / '));
  return labels.filter(Boolean).join(' / ');
})()
